from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected exactly one replacement anchor, found {count}")
    p.write_text(text.replace(old, new, 1), encoding="utf-8")


# P1: AE is a derived observable (AE = |e|).  Do not allow caller-supplied AE
# to disagree with signed error and then participate in the absolute gates.
replace_once(
    "voice_genesis/calibration/gates.py",
    '''    nonfinite_primary_budget_ids = sorted(\n        i.instance_id\n        for i in primary\n        if not _all_finite((i.ae, i.u_gt, i.u_num, i.e_use))\n    )\n    invalid_primary_budget_ids = sorted(\n        i.instance_id\n        for i in primary\n        if not (\n            _nonnegative_finite(i.ae)\n            and _nonnegative_finite(i.u_gt)\n            and _nonnegative_finite(i.u_num)\n            and _positive_finite(i.e_use)\n        )\n    )\n    budget_inputs_valid = global_uncertainty_valid and not invalid_primary_budget_ids\n''',
    '''    nonfinite_primary_budget_ids = sorted(\n        i.instance_id\n        for i in primary\n        if not _all_finite((i.ae, i.e, i.u_gt, i.u_num, i.e_use))\n    )\n    invalid_primary_budget_ids = sorted(\n        i.instance_id\n        for i in primary\n        if not (\n            _nonnegative_finite(i.ae)\n            and math.isfinite(i.e)\n            and _nonnegative_finite(i.u_gt)\n            and _nonnegative_finite(i.u_num)\n            and _positive_finite(i.e_use)\n        )\n    )\n    ae_mismatch_ids = sorted(\n        i.instance_id\n        for i in primary\n        if math.isfinite(i.ae) and math.isfinite(i.e) and i.ae != abs(i.e)\n    )\n    budget_inputs_valid = (\n        global_uncertainty_valid and not invalid_primary_budget_ids and not ae_mismatch_ids\n    )\n''',
)
replace_once(
    "voice_genesis/calibration/gates.py",
    '''    if invalid_primary_budget_ids:\n        reasons.append(\n            "gate budgets: PRIMARY AE/U_GT/U_num must be finite/nonnegative and E_use > 0: "\n            + ", ".join(invalid_primary_budget_ids)\n        )\n\n    gate1 = all(i.eligible for i in primary) and not duplicate_instance_ids\n''',
    '''    if invalid_primary_budget_ids:\n        reasons.append(\n            "gate budgets: PRIMARY AE/e/U_GT/U_num must be finite, "\n            "AE/U_GT/U_num nonnegative, and E_use > 0: "\n            + ", ".join(invalid_primary_budget_ids)\n        )\n    if ae_mismatch_ids:\n        reasons.append(\n            "gate1: PRIMARY AE must equal abs(e): " + ", ".join(ae_mismatch_ids)\n        )\n\n    gate1 = (\n        all(i.eligible for i in primary)\n        and not duplicate_instance_ids\n        and not ae_mismatch_ids\n    )\n''',
)

# P1: authenticate non-empty frozen stratification instead of hard-coding the
# unstratified special case.  Factor names are committed by realized_sha; values
# are independently reconstructed from the canonical matrix, not caller input.
replace_once(
    "voice_genesis/calibration/provenance.py",
    '''        canonical_split_inputs = {\n            matrix_row.row_id: RowInput(\n                row_id=matrix_row.row_id,\n                family=matrix_row.row.family,\n                stratum={},\n                truth_level=matrix_row.row.block,\n                generator_impl=matrix_row.row.generator_impl,\n                boundary_class=matrix_row.domain.value,\n            )\n            for matrix_row in canonical_matrix\n        }\n        for supplied in split_verification_rows:\n            expected = canonical_split_inputs[supplied.row_id]\n            if (\n                supplied.family != expected.family\n                or dict(supplied.stratum) != dict(expected.stratum)\n                or supplied.truth_level != expected.truth_level\n                or supplied.generator_impl != expected.generator_impl\n                or supplied.boundary_class != expected.boundary_class\n            ):\n                return LeakageCheckResult(\n                    blocked=BlockedCode.BLOCKED_LEAKAGE, control_excluded_count=0\n                )\n        if tuple(realized_split_map.stratum_factor_names) != ():\n            return LeakageCheckResult(blocked=BlockedCode.BLOCKED_LEAKAGE, control_excluded_count=0)\n''',
    '''        stratum_factor_names = tuple(realized_split_map.stratum_factor_names)\n        if (\n            any(\n                not isinstance(name, str) or not name.strip()\n                for name in stratum_factor_names\n            )\n            or len(stratum_factor_names) != len(set(stratum_factor_names))\n        ):\n            return LeakageCheckResult(blocked=BlockedCode.BLOCKED_LEAKAGE, control_excluded_count=0)\n\n        canonical_split_inputs: dict[str, RowInput] = {}\n        for matrix_row in canonical_matrix:\n            fixture_row = matrix_row.row\n            dataclass_fields = type(fixture_row).__dataclass_fields__\n            canonical_stratum: dict[str, Any] = {}\n            for factor_name in stratum_factor_names:\n                if factor_name == "truth_level":\n                    factor_value = fixture_row.block\n                elif factor_name in {"boundary_class", "domain"}:\n                    factor_value = matrix_row.domain.value\n                elif factor_name in dataclass_fields:\n                    factor_value = getattr(fixture_row, factor_name)\n                else:\n                    return LeakageCheckResult(\n                        blocked=BlockedCode.BLOCKED_LEAKAGE, control_excluded_count=0\n                    )\n                try:\n                    hash(factor_value)\n                except TypeError:\n                    return LeakageCheckResult(\n                        blocked=BlockedCode.BLOCKED_LEAKAGE, control_excluded_count=0\n                    )\n                canonical_stratum[factor_name] = factor_value\n\n            canonical_split_inputs[matrix_row.row_id] = RowInput(\n                row_id=matrix_row.row_id,\n                family=fixture_row.family,\n                stratum=canonical_stratum,\n                truth_level=fixture_row.block,\n                generator_impl=fixture_row.generator_impl,\n                boundary_class=matrix_row.domain.value,\n            )\n\n        for supplied in split_verification_rows:\n            expected = canonical_split_inputs[supplied.row_id]\n            if (\n                supplied.family != expected.family\n                or dict(supplied.stratum) != dict(expected.stratum)\n                or supplied.truth_level != expected.truth_level\n                or supplied.generator_impl != expected.generator_impl\n                or supplied.boundary_class != expected.boundary_class\n            ):\n                return LeakageCheckResult(\n                    blocked=BlockedCode.BLOCKED_LEAKAGE, control_excluded_count=0\n                )\n''',
)

# Regression: reviewer exploit cannot hide signed error behind forged AE.
with Path("voice_genesis/calibration/tests/test_gates.py").open("a", encoding="utf-8") as f:
    f.write('''\n\ndef test_absolute_gates_rejects_ae_signed_error_mismatch() -> None:\n    instances = [\n        _instance("ae-mismatch-pos", ae=0.0, e=100.0, u_gt=0.0, u_num=0.0, e_use=1.0),\n        _instance("ae-mismatch-neg", ae=0.0, e=-100.0, u_gt=0.0, u_num=0.0, e_use=1.0),\n    ]\n    result = absolute_gates(\n        instances,\n        u_rep=0.0,\n        u_proc=0.0,\n        invariance_pairs_by_axis={"axis1": _inv_pairs("axis1", 5)},\n        declared_invariance_axes={"axis1"},\n        fdr0=0.0,\n        fnr1=0.0,\n        min_count_met=True,\n    )\n\n    assert result.gate1_all_eligible is False\n    assert result.g_values == ()\n    assert result.passed is False\n    assert any("AE must equal abs(e)" in reason for reason in result.failure_reasons)\n''')

# Regression: a legitimate non-empty C0 stratum factor can authenticate, while
# row-level values remain canonical and cannot be supplied arbitrarily.
with Path("voice_genesis/calibration/tests/test_provenance.py").open("a", encoding="utf-8") as f:
    f.write('''\n\ndef test_check_leakage_authenticates_nonempty_frozen_stratification() -> None:\n    from voice_genesis.calibration.vocab import Split\n\n    matrix = build_matrix()\n    rows = tuple(\n        RowInput(\n            row_id=matrix_row.row_id,\n            family=matrix_row.row.family,\n            stratum={"block": matrix_row.row.block},\n            truth_level=matrix_row.row.block,\n            generator_impl=matrix_row.row.generator_impl,\n            boundary_class=matrix_row.domain.value,\n        )\n        for matrix_row in matrix\n    )\n    secret = hashlib.sha256(b"canonical-stratified-split").digest()\n    realized = realize_split(rows, secret, ("block",))\n    holdout = tuple(\n        row_id\n        for row_id, split in realized.assignment.items()\n        if split == Split.HOLDOUT\n    )\n    split_payload = {\n        "kind": "split_frozen",\n        "realized_split_map_hash": realized.realized_sha,\n        "seal_commitment": hashlib.sha256(secret).hexdigest(),\n    }\n    split_entry = LedgerEntry(\n        seq=0,\n        prev_sha=GENESIS_PREV_SHA,\n        entry_sha=_entry_sha(0, GENESIS_PREV_SHA, split_payload),\n        payload=split_payload,\n    )\n\n    result = Ledger.check_leakage(\n        (split_entry,),\n        holdout_row_ids=holdout,\n        unseal_seq=None,\n        realized_split_map=realized,\n        split_verification_rows=rows,\n        split_secret=secret,\n    )\n\n    assert result.blocked is None\n\n\ndef test_check_leakage_rejects_forged_value_for_frozen_stratum_factor() -> None:\n    from voice_genesis.calibration.vocab import Split\n\n    matrix = build_matrix()\n    rows = [\n        RowInput(\n            row_id=matrix_row.row_id,\n            family=matrix_row.row.family,\n            stratum={"block": matrix_row.row.block},\n            truth_level=matrix_row.row.block,\n            generator_impl=matrix_row.row.generator_impl,\n            boundary_class=matrix_row.domain.value,\n        )\n        for matrix_row in matrix\n    ]\n    target = rows[0]\n    rows[0] = RowInput(\n        row_id=target.row_id,\n        family=target.family,\n        stratum={"block": "FORGED_BLOCK"},\n        truth_level=target.truth_level,\n        generator_impl=target.generator_impl,\n        boundary_class=target.boundary_class,\n    )\n    secret = hashlib.sha256(b"forged-stratified-split").digest()\n    forged_realized = realize_split(rows, secret, ("block",))\n    holdout = tuple(\n        row_id\n        for row_id, split in forged_realized.assignment.items()\n        if split == Split.HOLDOUT\n    )\n    split_payload = {\n        "kind": "split_frozen",\n        "realized_split_map_hash": forged_realized.realized_sha,\n        "seal_commitment": hashlib.sha256(secret).hexdigest(),\n    }\n    split_entry = LedgerEntry(\n        seq=0,\n        prev_sha=GENESIS_PREV_SHA,\n        entry_sha=_entry_sha(0, GENESIS_PREV_SHA, split_payload),\n        payload=split_payload,\n    )\n\n    result = Ledger.check_leakage(\n        (split_entry,),\n        holdout_row_ids=holdout,\n        unseal_seq=None,\n        realized_split_map=forged_realized,\n        split_verification_rows=tuple(rows),\n        split_secret=secret,\n    )\n\n    assert result.blocked == BlockedCode.BLOCKED_LEAKAGE\n''')
